import Foundation

/// How the accounts list marks a login's provider: the provider's logo where Simple Icons
/// has one, else a rounded tile with a two-letter code. Both draw monochrome, like SF Symbols.
public enum ProviderMark: Sendable, Equatable {
    case logo(SimpleIcon)
    case letters(String)

    /// `nil` for a provider Ebb has no mark for; `letters(forName:)` covers those.
    public static func forProvider(named proxyName: String) -> ProviderMark? {
        known[proxyName.lowercased()]
    }

    /// "Op" for "openrouter": the first two letters, for providers without a mark.
    public static func letters(forName name: String) -> String {
        let letters = name.filter(\.isLetter)
        return letters.prefix(1).uppercased() + letters.dropFirst().prefix(1).lowercased()
    }

    /// Keyed by CLIProxyAPI's provider name. Codes follow the tiles in the design record:
    /// two letters, because single initials collide (Claude and Codex, Gemini and Grok).
    private static let known: [String: ProviderMark] = [
        "claude": .logo(.claude),
        "kimi": .logo(.kimi),
        "meta": .logo(.meta),
        "qwen": .logo(.qwen),
        "gemini": .logo(.gemini),
        "gemini-cli": .logo(.gemini),
        "gemini-interactions": .logo(.gemini),
        "codex": .letters("Cx"),
        "devin": .letters("Dv"),
        "antigravity": .letters("Ag"),
        "vertex": .letters("Vx"),
        "aistudio": .letters("AS"),
        "iflow": .letters("iF"),
        "xai": .letters("Gk"),
        "grok": .letters("Gk"),
    ]
}

